<section class="admin-page-head"><div><p class="admin-kicker">M07 · CLIENTES INTERNOS</p><h1>Clientes</h1><p>Directorio comercial por sucursal. Un cliente no obtiene acceso al panel.</p></div><?php if($capabilities['customers.create']??false):?><a class="admin-primary-button" href="/admin/customers/create">+ Nuevo cliente</a><?php endif?></section>
<form class="admin-panel admin-filter-bar" method="get"><label class="admin-field"><span>Buscar</span><input type="search" name="q" maxlength="120" value="<?= e($q) ?>" placeholder="Código, nombre, RFC o correo"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><option value="">Todas autorizadas</option><?php foreach($branches as$b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Tipo</span><select name="type"><option value="">Todos</option><option value="individual" <?= $type==='individual'?'selected':'' ?>>Persona</option><option value="business" <?= $type==='business'?'selected':'' ?>>Empresa</option></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="all">Todos</option><option value="active" <?= $status==='active'?'selected':'' ?>>Activos</option><option value="inactive" <?= $status==='inactive'?'selected':'' ?>>Inactivos</option></select></label><button class="admin-secondary-button">Aplicar</button></form>
<section class="admin-panel admin-table-panel"><?php if($page->items===[]):?><div class="admin-empty"><strong>Sin clientes</strong><span>No se cargan clientes ficticios. Registra uno cuando sus datos estén confirmados.</span></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Cliente</th><th>Contacto</th><th>Sucursal</th><th>Tipo</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($page->items as$c):?><tr><td data-label="Cliente"><strong><?= e($c['legal_name']) ?></strong><small><?= e($c['code'].($c['trade_name']?' · '.$c['trade_name']:'')) ?></small></td><td data-label="Contacto"><?= e($c['email']??'Sin correo') ?><small><?= e($c['phone']??'') ?></small></td><td data-label="Sucursal"><?= e($c['branch_name']) ?></td><td data-label="Tipo"><?= $c['customer_type']==='business'?'Empresa':'Persona' ?></td><td data-label="Estado"><span class="admin-status <?= (int)$c['is_active']===1?'is-active':'is-danger' ?>"><?= (int)$c['is_active']===1?'Activo':'Inactivo' ?></span></td><td class="admin-actions"><a class="admin-secondary-button" href="/admin/customers/detail?id=<?= e($c['id']) ?>">Detalle</a><?php if($capabilities['customers.edit']??false):?><a class="admin-quiet-button" href="/admin/customers/edit?id=<?= e($c['id']) ?>">Editar</a><?php endif?><?php if($capabilities['customers.status']??false):?><form method="post" action="/admin/customers/status"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($c['id']) ?>"><input type="hidden" name="lock_version" value="<?= e($c['lock_version']) ?>"><input type="hidden" name="active" value="<?= (int)$c['is_active']===1?'0':'1' ?>"><button class="admin-quiet-button" data-confirm="¿Confirmas el cambio de estado?"><?= (int)$c['is_active']===1?'Desactivar':'Activar' ?></button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><nav class="admin-pagination" aria-label="Paginación"><?php if($page->offset>0):?><a class="admin-secondary-button" href="?q=<?= urlencode($q) ?>&amp;status=<?= e($status) ?>&amp;type=<?= e($type??'') ?>&amp;branch_id=<?= e($branchId??'') ?>&amp;offset=<?= max(0,$page->offset-$page->limit) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a class="admin-secondary-button" href="?q=<?= urlencode($q) ?>&amp;status=<?= e($status) ?>&amp;type=<?= e($type??'') ?>&amp;branch_id=<?= e($branchId??'') ?>&amp;offset=<?= $page->offset+$page->limit ?>">Siguiente</a><?php endif?></nav><?php endif?></section>
